<?php
require_once('../../init.php');
require_once('auth/session.php');
require 'vendor/autoload.php';

use Dompdf\Dompdf;
use Dompdf\Options;
use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;

// Configuración de zona horaria
date_default_timezone_set('America/Tijuana');

// Obtén la fecha seleccionada desde el request
$dateReq = isset($_POST['dateReq']) ? $_POST['dateReq'] : null;
$catMisa = isset($_POST['misaReq']) ? $_POST['misaReq'] : null;
// Validar que se haya proporcionado la fecha
if (!$dateReq) {
    die("Fecha requerida");
}


    $headers = [
        'Authorization' => 'Bearer '.$token,
    ];

    $client = new Client([
        'base_uri' => API_SERVICES,
        'headers' => $headers,
    ]);

    try {
        $response = $client->request('GET', 'misa_intents/all');
        $data = json_decode($response->getBody()->getContents(), true);
    
        // Filtrar los registros por la fecha seleccionada
        $filteredData = array_filter($data, function ($item) use ($dateReq, $catMisa) {
            // Validar fecha
            $dateMatch = isset($item['date']) && date('Y-m-d', strtotime($item['date'])) === $dateReq;
        
            // Validar misa_id
            $hourMatch = !$catMisa || (isset($item['misa_hour']) && $item['misa_hour'] === $catMisa);
        
            return $dateMatch && $hourMatch;
        });

    
        // Obtener horas únicas
        $hours = array_unique(array_map(function ($item) {
            return $item['misa_hour'];
        }, $filteredData));
    
        // Concatenar horas con un separador (coma o espacio)
        $HOUR = implode(", ", $hours);
    
        // Agrupar por intenciones
        $groupedData = [];
        foreach ($filteredData as $item) {
            $groupedData[$item['intent']][] = $item;
        }
    
        //$logoBase64 = base64_encode(file_get_contents('C:/xampp/htdocs/Church/Application/assets/img/LOGO_CATEDRAL_TIJUANA.png'));
    
        // HTML para el PDF
        $html = "
        <html>
        <head>
            <style>
                body { font-family: Arial, sans-serif; font-size: 12px; margin: 0; padding: 0; }
                .header { text-align: center; font-weight: bold; margin-bottom: 20px; }
                .header div { font-size: 14px; }
                .header h2 { margin: 5px 0; }
                .details { text-align: center; font-size: 16px; margin-bottom: 20px; margin-top:-100px }
                table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                th, td { border: 1px solid #000; padding: 5px; text-align: left; }
                .table-section { font-weight: bold; text-align: center; background-color: #f0f0f0; }
            </style>
        </head>
        <body>
            
               <table  cellspacing='0' cellpadding='0' style='border: none !important; width: 100%;'>
                    <tbody>
                        <tr>
                            <td rowspan='4' style='border: none !important; vertical-align: top; width: 30%; position: relative;'>
                            <img src='data:image/png;base64,<> width='140' height='140' alt='Logo'>
                            </td>
                        </tr>
                        <tr>
                            <td colspan='2' style='border: none !important; vertical-align: middle; width: 70%; '>
                                <h3 style='margin: 0;'>CATEDRAL METROPOLITANA DE TIJUANA, DEDICADA A SANTA MARÍA DE GUADALUPE, ZONA RÍO</h3>
                                <br><h2>Intenciones</h2>
                            </td>
                        </tr>
                    </tbody>
                </table>
            
            <div class='details'>
                <p>Día: <b>". date('d/m/Y', strtotime($dateReq)) . "</b>&nbsp;&nbsp; HORA: ".$HOUR."</p>
            </div>";
    
        
        $hasMultipleHours = count($hours) > 1; // Verifica si hay más de 2 horas únicas

        foreach ($groupedData as $intent => $records) {
            // Cabecera de la tabla
            $html .= "<table>
                <tr class='table-section'>
                    <td colspan='" . ($hasMultipleHours ? '3' : '2') . "'>" . strtoupper($intent) . "</td>
                </tr>
                <tr>
                    <th>Nombre</th>
                    <th>Descripción</th>";
            if ($hasMultipleHours) {
                $html .= "<th>Hora</th>";
            }
            $html .= "</tr>";

            // Filas de la tabla
            foreach ($records as $record) {
                $html .= "<tr>
                    <td>" . htmlspecialchars($record['mention_person']) . "</td>
                    <td>" . htmlspecialchars($record['decription']) . "</td>";
                if ($hasMultipleHours) {
                    $html .= "<td>" . htmlspecialchars($record['misa_hour']) . "</td>";
                }
                $html .= "</tr>";
            }
            $html .= "</table>";
        }

        $html .= "</body></html>";
    
        // Configuración de Dompdf
        $options = new Options();
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isRemoteEnabled', true);
        $dompdf = new Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
    
        // Generar PDF
        $dompdf->stream("intenciones_" . $dateReq . ".pdf", ["Attachment" => true]);
    } catch (RequestException $e) {
        echo "Error al obtener las intenciones: " . $e->getMessage();
    }
    